  var level = p.level;
  var LE = Java.loadClass('net.minecraft.world.entity.LivingEntity');
  var MI = Java.loadClass('com.merlinkitsune.astral_dice.item.ModItems');
  var cleared = 0; var items = p.getInventory().items;
  for (var i = 0; i < items.size(); i++) { var st = items.get(i); if (st != null && !st.isEmpty() && MI.isCardItem(st)) { cleared += st.getCount(); st.setCount(0); } }
  return {ok:true, cleared:cleared};
})()

(function(){
  var server = Java.loadClass('net.neoforged.neoforge.server.ServerLifecycleHooks').getCurrentServer();
  var p = server.getPlayerList().getPlayers().get(0);
  var level = p.level;
  var LE = Java.loadClass('net.minecraft.world.entity.LivingEntity');
  var ET = Java.loadClass('net.minecraft.world.entity.EntityType');
  var MM = Java.loadClass('com.merlinkitsune.astral_dice.item.MarkManager');
  var old = level.getEntitiesOfClass(LE, p.getBoundingBox().inflate(48));
  for (var i = 0; i < old.size(); i++) { if (old.get(i).getTags().contains('SW_T')) old.get(i).discard(); }
  var ent = ET.PILLAGER.create(level);
  ent.setPos(p.getX() + 2.5, p.getY(), p.getZ() + 0.5);
  ent.setNoAi(true); ent.addTag('SW_T'); level.addFreshEntity(ent);
  MM.apply(ent); ent.setHealth(1.0);
  return {ok:true, hp: ent.getHealth(), marked: MM.getLevel(ent)};
})()

