(function(){
  var server = Java.loadClass('net.neoforged.neoforge.server.ServerLifecycleHooks').getCurrentServer();
  var p = server.getPlayerList().getPlayers().get(0);
  var level = p.level;
  var LE = Java.loadClass('net.minecraft.world.entity.LivingEntity');
  var ET = Java.loadClass('net.minecraft.world.entity.EntityType');
  var list = level.getEntitiesOfClass(LE, p.getBoundingBox().inflate(90));
  for (var i = 0; i < list.size(); i++) { var tg = list.get(i).getTags(); var kill = false; var it = tg.iterator(); while (it.hasNext()) { var s = '' + it.next(); if (s.indexOf('MU') === 0 || s.indexOf('MT') === 0) { kill = true; } } if (kill) { list.get(i).discard(); } }
  var made = 0;
  function mkOne(tag, dx, dz, tracked) { var e = ET.PILLAGER.create(level); e.setPos(p.getX() + dx, p.getY(), p.getZ() + dz); e.setNoAi(true); e.addTag(tag); level.addFreshEntity(e); e.setHealth(20.0); if (tracked) { e.setTarget(p); } return e; }
  for (var u = 0; u < 16; u++) { mkOne('MU' + u, 1.5 + (u % 4) * 1.0, 16.0 + Math.floor(u / 4) * 1.0, false); made++; }
  for (var t = 0; t < 16; t++) { mkOne('MT' + t, 1.5 + (t % 4) * 1.0, -2.0 - Math.floor(t / 4) * 1.0, true); made++; }
  return {ok:true, made:made};
})()

(function(){
  var server = Java.loadClass('net.neoforged.neoforge.server.ServerLifecycleHooks').getCurrentServer();
  var p = server.getPlayerList().getPlayers().get(0);
  var level = p.level;
  var LE = Java.loadClass('net.minecraft.world.entity.LivingEntity');
  var MM = Java.loadClass('com.merlinkitsune.astral_dice.item.MarkManager');
  var LSM = Java.loadClass('com.merlinkitsune.astral_dice.item.sign.LinglingSignManager');
  var SC = Java.loadClass('com.merlinkitsune.astral_dice.item.sign.SignEquipCheck');
  var MI = Java.loadClass('com.merlinkitsune.astral_dice.item.ModItems');
  var list = level.getEntitiesOfClass(LE, p.getBoundingBox().inflate(90));
  var ents = {};
  for (var i = 0; i < list.size(); i++) { var tg = list.get(i).getTags(); var it = tg.iterator(); while (it.hasNext()) { ents['' + it.next()] = list.get(i); } }
  var srcU = [], srcT = [], marksOk = 1, trackedOk = 1;
  for (var k = 0; k < 16; k++) {
    var u = ents['MU' + k]; var t = ents['MT' + k];
    if (u == null || t == null) { continue; }
    u.setHealth(20.0); t.setHealth(20.0);
    MM.apply(u); MM.apply(t);
    if (MM.getLevel(u) !== 1 || MM.getLevel(t) !== 1) { marksOk = 0; }
    if (!LSM.isTrackedByAny(t)) { trackedOk = 0; }
    var hu0 = u.getHealth(); var ht0 = t.getHealth();
    server.getCommands().performPrefixedCommand(p.createCommandSourceStack().withSuppressedOutput(), 'damage @e[tag=MU' + k + ',limit=1] 1 astral_dice:card_spell by @s');
    server.getCommands().performPrefixedCommand(p.createCommandSourceStack().withSuppressedOutput(), 'damage @e[tag=MT' + k + ',limit=1] 1 astral_dice:card_spell by @s');
    srcU.push(hu0 - u.getHealth()); srcT.push(ht0 - t.getHealth());
  }
  var n = srcU.length; var diff = []; var near5 = 0; var near0 = 0;
  for (var j = 0; j < n; j++) { var d = srcT[j] - srcU[j]; diff.push(d); if (d >= 4.0 && d <= 6.0) { near5++; } if (d >= -1.0 && d <= 1.0) { near0++; } }
  var sorted = diff.slice(0); sorted.sort(function(a, b) { return a - b; });
  var median = -1;
  if (n > 0) { if (n % 2 === 1) { median = sorted[(n - 1) / 2]; } else { median = (sorted[n / 2 - 1] + sorted[n / 2]) / 2; } }
  var hasSign = SC.isEquipped(p, MI.LINGLING_SIGN.get());
  return {ok:true, n:n, median:median, near5:near5, near0:near0, srcU:srcU, srcT:srcT, diff:diff, marksOk:marksOk, trackedOk:trackedOk, hasSign:hasSign};
})()

